export class DsCheckboxGroup extends LitElement {
  static override styles = [unsafeCSS(':host { display: contents; }'), unsafeCSS(css)];
  static override properties = {
    legend: { type: String },
    orientation: { type: String, reflect: true },
    error: { type: String },
    warning: { type: String },
    readOnly: { type: Boolean, attribute: 'readonly' },
    disabled: { type: Boolean, reflect: true },
  };

  declare legend: string;
  /** Figma: CheckboxGroup Orientation. */
  declare orientation: "vertical" | "horizontal";
  declare error: string | undefined;
  declare warning: string | undefined;
  declare readOnly: boolean;
  declare disabled: boolean;

  constructor() {
    super();
    this.legend = '';
    this.orientation = "vertical";
    this.readOnly = false;
    this.disabled = false;
  }

  /** Read-only and disabled apply to every checkbox inside. */
  override updated() {
    for (const el of this.querySelectorAll('ds-checkbox')) {
      el.groupReadOnly = this.readOnly;
      el.groupDisabled = this.disabled;
    }
  }

  override render() {
    const hasMessage = Boolean(this.error || this.warning);
    return html`<fieldset class="group" data-orientation=${this.orientation} ?data-invalid=${Boolean(this.error)} ?data-warning=${Boolean(this.warning) && !this.error} ?data-readonly=${this.readOnly} aria-describedby=${hasMessage ? 'message' : nothing} ?disabled=${this.disabled}>
      <legend class="legend">${this.legend}</legend>
      <div class="items"><slot @slotchange=${() => this.requestUpdate()}></slot></div>
      ${this.error ? html`<span id="message" class="groupErrorRow"><span class="groupErrorIcon" aria-hidden="true">${icon("statusError16")}</span><span class="groupErrorText">${this.error}</span></span>` : nothing}
      ${this.warning && !this.error ? html`<span id="message" class="groupWarningRow"><span class="groupWarningIcon" aria-hidden="true">${icon("statusWarning16")}</span><span class="groupWarningText">${this.warning}</span></span>` : nothing}
    </fieldset>`;
  }
}

